def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = 0

    # Find full-width horizontal divider rows.
    dividers = [
        r for r, row in enumerate(grid)
        if len(set(row)) == 1 and row[0] != bg
    ]

    for i, d in enumerate(dividers):
        top = (dividers[i - 1] + 1) if i > 0 else 0
        bottom = (dividers[i + 1] - 1) if i + 1 < len(dividers) else h - 1

        upper_colors = {grid[r][c] for r in range(top, d) for c in range(w)
                        if grid[r][c] not in (bg, grid[d][0])}
        lower_colors = {grid[r][c] for r in range(d + 1, bottom + 1) for c in range(w)
                        if grid[r][c] not in (bg, grid[d][0])}

        for color in upper_colors & lower_colors:
            for r in range(top, d):
                rr = 2 * d - r
                if d < rr <= bottom:
                    for c in range(w):
                        if grid[r][c] == color:
                            out[rr][c] = color
            for r in range(d + 1, bottom + 1):
                rr = 2 * d - r
                if top <= rr < d:
                    for c in range(w):
                        if grid[r][c] == color:
                            out[rr][c] = color

    return out
